    private void processClassTable(List<FeatureEntity> features) {

        Map<String, String> columnTitles = new HashMap<>();
        columnTitles.put("PROFICIENCY_BONUS", "Prof Bonus");
        columnTitles.put("MARTIAL_ARTS", "Martial Arts");
        columnTitles.put("KI_POINTS", "Ki Points");
        columnTitles.put("UNARMORED_MOVEMENT", "Movement");
        columnTitles.put("CANTRIPS_KNOWN", "Cantrips");
        columnTitles.put("SPELLS_KNOWN", "Spells Known");
        columnTitles.put("SPELL_SLOTS", "Spell Slots");
        columnTitles.put("CLASS_FEATURE", "Class Features");
        columnTitles.put("RAGES", "Rages");
        columnTitles.put("RAGE_DAMAGE", "Rage Damage");
        columnTitles.put("SLOTS_1ST", "1st");
        columnTitles.put("SLOTS_2ND", "2nd");
        columnTitles.put("SLOTS_3RD", "3rd");
        columnTitles.put("SLOTS_4TH", "4th");
        columnTitles.put("SLOTS_5TH", "5th");
        columnTitles.put("SLOTS_6TH", "6th");
        columnTitles.put("SLOTS_7TH", "7th");
        columnTitles.put("SLOTS_8TH", "8th");
        columnTitles.put("SLOTS_9TH", "9th");

        Map<Integer, Map<String, String>> levelData = new HashMap<>();
        Set<String> availableColumns = new HashSet<>();

        Log.d("ClassTable", "=== DEBUG ALL FEATURES ===");
        for (FeatureEntity feature : features) {
            Log.d("ClassTable", "Feature: " + feature.name +
                    ", Type: " + feature.featureType +
                    ", TableData: " + (feature.tableData != null ? feature.tableData.size() : "null"));

            if (feature.tableData != null && !feature.tableData.isEmpty() &&
                    feature.featureType != null) {

                String columnTitle;

                if ("CLASS_FEATURE".equals(feature.featureType) &&
                        ("Rages".equals(feature.name) || "Rage Damage".equals(feature.name))) {
                    columnTitle = feature.name;
                }
                else if ("SPELL_SLOTS".equals(feature.featureType)) {
                    columnTitle = feature.name;
                }
                else if (columnTitles.containsKey(feature.featureType)) {
                    columnTitle = columnTitles.get(feature.featureType);
                } else {
                    continue;
                }

                Log.d("ClassTable", "✅ Processing table data for: " + feature.name +
                        " (" + feature.featureType + ") as column: " + columnTitle);

                availableColumns.add(columnTitle);

                for (TableData tableData : feature.tableData) {
                    if (!levelData.containsKey(tableData.level)) {
                        levelData.put(tableData.level, new HashMap<>());
                    }
                    levelData.get(tableData.level).put(columnTitle, tableData.columnValue);
                }
            }

            if (feature.gainedAt != null && !feature.gainedAt.isEmpty()) {
                for (GainedAt gainedAt : feature.gainedAt) {
                    if (gainedAt.level > 0) {
                        if (!levelData.containsKey(gainedAt.level)) {
                            levelData.put(gainedAt.level, new HashMap<>());
                        }

                        String currentFeatures = levelData.get(gainedAt.level).getOrDefault("Features", "");
                        String featureInfo = feature.name;
                        if (gainedAt.detail != null && !gainedAt.detail.isEmpty()) {
                            featureInfo += " (" + gainedAt.detail + ")";
                        }

                        if (!currentFeatures.isEmpty()) {
                            currentFeatures += ", " + featureInfo;
                        } else {
                            currentFeatures = featureInfo;
                        }

                        levelData.get(gainedAt.level).put("Features", currentFeatures);
                        availableColumns.add("Features");
                    }
                }
            }
        }

        Log.d("ClassTable", "=== DEBUG levelData ===");
        for (Integer level : levelData.keySet()) {
            Log.d("ClassTable", "Level " + level + ": " + levelData.get(level));
        }
        Log.d("ClassTable", "Available columns: " + availableColumns);
        Log.d("ClassTable", "Level data size: " + levelData.size());

        if (!levelData.isEmpty()) {
            List<String> columnHeaders = new ArrayList<>();
            columnHeaders.add("Level");

            List<String> priorityColumns = Arrays.asList("Prof Bonus", "Features", "Martial Arts",
                    "Ki Points", "Movement", "Rages", "Rage Damage",
                    "Cantrips", "Spells Known", "1st", "2nd", "3rd", "4th", "5th", "6th", "7th", "8th", "9th");

            for (String priorityCol : priorityColumns) {
                if (availableColumns.contains(priorityCol)) {
                    columnHeaders.add(priorityCol);
                }
            }

            for (String column : availableColumns) {
                if (!columnHeaders.contains(column)) {
