    private void setupFullClassTable(List<String> columnHeaders, Map<Integer, Map<String, String>> levelData) {
        TableLayout fullTable = findViewById(R.id.full_class_table);
        fullTable.removeAllViews();
        fullTable.setStretchAllColumns(true);

        TableRow headerRow = new TableRow(this);
        headerRow.setLayoutParams(new TableLayout.LayoutParams(
                TableLayout.LayoutParams.WRAP_CONTENT,
                TableLayout.LayoutParams.WRAP_CONTENT
        ));

        for (int i = 0; i < columnHeaders.size(); i++) {
            String header = columnHeaders.get(i);
            TextView headerView = createHeaderCell(header, i == 0);
            headerRow.addView(headerView);
        }
        fullTable.addView(headerRow);

        for (int level = 1; level <= 20; level++) {
            TableRow dataRow = new TableRow(this);
            dataRow.setLayoutParams(new TableLayout.LayoutParams(
                    TableLayout.LayoutParams.WRAP_CONTENT,
                    TableLayout.LayoutParams.WRAP_CONTENT
            ));

            for (int i = 0; i < columnHeaders.size(); i++) {
                String columnName = columnHeaders.get(i);
                TextView dataCell = createDataCell(columnName, level, levelData, i == 0);
                dataRow.addView(dataCell);
            }
            fullTable.addView(dataRow);
        }
    }

    private TextView createHeaderCell(String header, boolean isFirstColumn) {
        TextView textView = new TextView(this);

        TableRow.LayoutParams params = new TableRow.LayoutParams(
                getHeaderWidth(header),
                TableRow.LayoutParams.WRAP_CONTENT
        );
        params.setMargins(dpToPx(1), dpToPx(1), dpToPx(1), dpToPx(1));
        textView.setLayoutParams(params);

        textView.setPadding(dpToPx(8), dpToPx(8), dpToPx(8), dpToPx(8));
        textView.setText(header);
        textView.setTypeface(null, Typeface.BOLD);
        textView.setBackgroundColor(getResources().getColor(android.R.color.darker_gray));
        textView.setTextColor(getResources().getColor(android.R.color.white));
        textView.setGravity(Gravity.CENTER);
        textView.setTextSize(12);
        textView.setSingleLine(false);
        textView.setMaxLines(2);
        textView.setEllipsize(TextUtils.TruncateAt.END);

        if (isFirstColumn) {
            textView.setBackgroundColor(Color.parseColor("#808080"));
        }

        return textView;
    }

    private TextView createDataCell(String columnName, int level, Map<Integer, Map<String, String>> levelData, boolean isFirstColumn) {
        TextView textView = new TextView(this);

        TableRow.LayoutParams params = new TableRow.LayoutParams(
                getHeaderWidth(columnName),
                TableRow.LayoutParams.WRAP_CONTENT
        );
        params.setMargins(dpToPx(1), dpToPx(1), dpToPx(1), dpToPx(1));
        textView.setLayoutParams(params);

        textView.setPadding(dpToPx(8), dpToPx(6), dpToPx(8), dpToPx(6));
        textView.setBackgroundResource(android.R.drawable.edit_text);
        textView.setTextSize(12);
        textView.setGravity(Gravity.CENTER);
        textView.setSingleLine(false);
        textView.setMaxLines(2);
        textView.setEllipsize(TextUtils.TruncateAt.END);

        if (isFirstColumn) {
            textView.setTypeface(null, Typeface.BOLD);
            textView.setBackgroundColor(Color.parseColor("#F0F0F0"));
        }

        String value;
        if (columnName.equals("Level")) {
            value = String.valueOf(level);
        } else {
            Map<String, String> levelRow = levelData.get(level);
            value = (levelRow != null && levelRow.containsKey(columnName)) ?
                    levelRow.get(columnName) : "-";
        }
        textView.setText(value);

        return textView;
    }

    private void processProficiencies(List<FeatureEntity> features) {
        FeatureEntity proficienciesFeature = null;
        for (FeatureEntity feature : features) {
            if ("PROFICIENCIES".equals(feature.featureType)) {
                proficienciesFeature = feature;
                break;
            }
        }

        if (proficienciesFeature != null) {
            String desc = proficienciesFeature.desc;

            TextView tvArmor = findViewById(R.id.tv_armor_proficiencies);
            TextView tvWeapon = findViewById(R.id.tv_weapon_proficiencies);
            TextView tvTool = findViewById(R.id.tv_tool_proficiencies);
            TextView tvSkills = findViewById(R.id.tv_skills);

            if (desc.contains("Armor:")) {
                String armorPart = desc.substring(desc.indexOf("Armor:") + 6);
                if (armorPart.contains("**")) {
                    armorPart = armorPart.substring(0, armorPart.indexOf("**"));
                }
                tvArmor.setText("Armor: " + armorPart.trim());
            } else {
                tvArmor.setVisibility(View.GONE);
            }

            if (desc.contains("Weapons:")) {
                String weaponPart = desc.substring(desc.indexOf("Weapons:") + 8);
                if (weaponPart.contains("**")) {
                    weaponPart = weaponPart.substring(0, weaponPart.indexOf("**"));
                }
                tvWeapon.setText("Weapons: " + weaponPart.trim());
            } else {
                tvWeapon.setVisibility(View.GONE);
            }

            if (desc.contains("Tools:")) {
                String toolPart = desc.substring(desc.indexOf("Tools:") + 6);
                if (toolPart.contains("**")) {
                    toolPart = toolPart.substring(0, toolPart.indexOf("**"));
                }
                tvTool.setText("Tools: " + toolPart.trim());
            } else {
                tvTool.setVisibility(View.GONE);
            }

            if (desc.contains("Skills:")) {
                String skillsPart = desc.substring(desc.indexOf("Skills:") + 7);
                if (skillsPart.contains("**")) {
                    skillsPart = skillsPart.substring(0, skillsPart.indexOf("**"));
                }
                tvSkills.setText("Skills: " + skillsPart.trim());
